using Microsoft.VisualStudio.TestTools.UnitTesting;
using Moq;
using Payments;

namespace Payments.Tests;

[TestClass]
public class PaymentGatewayTests
{
    private Mock<IPaymentProcessor> _processorMock = null!;
    private PaymentGateway _gateway = null!;

    [TestInitialize]
    public void Setup()
    {
        _processorMock = new Mock<IPaymentProcessor>();
        _gateway = new PaymentGateway(_processorMock.Object);
    }

    // ── Constructor ──────────────────────────────────────────

    [TestMethod]
    public void Constructor_NullProcessor_ThrowsArgumentNullException()
    {
        Assert.ThrowsException<ArgumentNullException>(() => new PaymentGateway(null!));
    }

    // ── ChargeAsync – positive ───────────────────────────────

    [TestMethod]
    public async Task ChargeAsync_ValidInput_ReturnsSuccess()
    {
        var expected = new ChargeResult("ch_123", true);
        _processorMock
            .Setup(p => p.ProcessChargeAsync("tok_visa", 49.99m))
            .ReturnsAsync(expected);

        var result = await _gateway.ChargeAsync("tok_visa", 49.99m);

        Assert.AreEqual(expected, result);
        _processorMock.Verify(p => p.ProcessChargeAsync("tok_visa", 49.99m), Times.Once);
    }

    [TestMethod]
    public async Task ChargeAsync_MinimumAmount_Succeeds()
    {
        _processorMock
            .Setup(p => p.ProcessChargeAsync("tok_visa", 0.01m))
            .ReturnsAsync(new ChargeResult("ch_min", true));

        var result = await _gateway.ChargeAsync("tok_visa", 0.01m);

        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_MaximumAllowedAmount_Succeeds()
    {
        _processorMock
            .Setup(p => p.ProcessChargeAsync("tok_visa", 999_999.99m))
            .ReturnsAsync(new ChargeResult("ch_max", true));

        var result = await _gateway.ChargeAsync("tok_visa", 999_999.99m);

        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_ProcessorReturnsFailed_ReturnsFailed()
    {
        _processorMock
            .Setup(p => p.ProcessChargeAsync(It.IsAny<string>(), It.IsAny<decimal>()))
            .ReturnsAsync(new ChargeResult("ch_fail", false));

        var result = await _gateway.ChargeAsync("tok_declined", 10m);

        Assert.IsFalse(result.Success);
    }

    // ── ChargeAsync – negative / validation ──────────────────

    [TestMethod]
    public async Task ChargeAsync_NullToken_ThrowsArgumentException()
    {
        await Assert.ThrowsExceptionAsync<ArgumentException>(
            () => _gateway.ChargeAsync(null!, 10m));
    }

    [TestMethod]
    public async Task ChargeAsync_EmptyToken_ThrowsArgumentException()
    {
        await Assert.ThrowsExceptionAsync<ArgumentException>(
            () => _gateway.ChargeAsync("", 10m));
    }

    [TestMethod]
    public async Task ChargeAsync_WhitespaceToken_ThrowsArgumentException()
    {
        await Assert.ThrowsExceptionAsync<ArgumentException>(
            () => _gateway.ChargeAsync("   ", 10m));
    }

    [TestMethod]
    public async Task ChargeAsync_ZeroAmount_ThrowsArgumentOutOfRangeException()
    {
        await Assert.ThrowsExceptionAsync<ArgumentOutOfRangeException>(
            () => _gateway.ChargeAsync("tok_visa", 0m));
    }

    [TestMethod]
    public async Task ChargeAsync_NegativeAmount_ThrowsArgumentOutOfRangeException()
    {
        await Assert.ThrowsExceptionAsync<ArgumentOutOfRangeException>(
            () => _gateway.ChargeAsync("tok_visa", -5m));
    }

    [TestMethod]
    public async Task ChargeAsync_ExceedsMaxAmount_ThrowsArgumentOutOfRangeException()
    {
        await Assert.ThrowsExceptionAsync<ArgumentOutOfRangeException>(
            () => _gateway.ChargeAsync("tok_visa", 1_000_000m));
    }

    [TestMethod]
    public async Task ChargeAsync_ProcessorThrows_ExceptionPropagates()
    {
        _processorMock
            .Setup(p => p.ProcessChargeAsync(It.IsAny<string>(), It.IsAny<decimal>()))
            .ThrowsAsync(new InvalidOperationException("Network error"));

        await Assert.ThrowsExceptionAsync<InvalidOperationException>(
            () => _gateway.ChargeAsync("tok_visa", 10m));
    }

    // ── RefundAsync – positive ───────────────────────────────

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccess()
    {
        var expected = new RefundResult("re_456", true);
        _processorMock
            .Setup(p => p.ProcessRefundAsync("ch_123"))
            .ReturnsAsync(expected);

        var result = await _gateway.RefundAsync("ch_123");

        Assert.AreEqual(expected, result);
        _processorMock.Verify(p => p.ProcessRefundAsync("ch_123"), Times.Once);
    }

    [TestMethod]
    public async Task RefundAsync_ProcessorReturnsFailed_ReturnsFailed()
    {
        _processorMock
            .Setup(p => p.ProcessRefundAsync(It.IsAny<string>()))
            .ReturnsAsync(new RefundResult("re_fail", false));

        var result = await _gateway.RefundAsync("ch_already_refunded");

        Assert.IsFalse(result.Success);
    }

    // ── RefundAsync – negative / validation ──────────────────

    [TestMethod]
    public async Task RefundAsync_NullChargeId_ThrowsArgumentException()
    {
        await Assert.ThrowsExceptionAsync<ArgumentException>(
            () => _gateway.RefundAsync(null!));
    }

    [TestMethod]
    public async Task RefundAsync_EmptyChargeId_ThrowsArgumentException()
    {
        await Assert.ThrowsExceptionAsync<ArgumentException>(
            () => _gateway.RefundAsync(""));
    }

    [TestMethod]
    public async Task RefundAsync_ProcessorThrows_ExceptionPropagates()
    {
        _processorMock
            .Setup(p => p.ProcessRefundAsync(It.IsAny<string>()))
            .ThrowsAsync(new InvalidOperationException("Not found"));

        await Assert.ThrowsExceptionAsync<InvalidOperationException>(
            () => _gateway.RefundAsync("ch_unknown"));
    }

    // ── ProcessWebhook – positive ────────────────────────────

    [TestMethod]
    public void ProcessWebhook_ChargeSucceeded_ReturnsHandled()
    {
        var result = _gateway.ProcessWebhook("charge.succeeded", "{\"id\":\"ch_1\"}");

        Assert.IsTrue(result.Handled);
        Assert.AreEqual("Charge confirmed", result.Message);
    }

    [TestMethod]
    public void ProcessWebhook_ChargeFailed_ReturnsHandled()
    {
        var result = _gateway.ProcessWebhook("charge.failed", "{\"id\":\"ch_2\"}");

        Assert.IsTrue(result.Handled);
        Assert.AreEqual("Charge failure recorded", result.Message);
    }

    [TestMethod]
    public void ProcessWebhook_RefundCompleted_ReturnsHandled()
    {
        var result = _gateway.ProcessWebhook("refund.completed", "{\"id\":\"re_1\"}");

        Assert.IsTrue(result.Handled);
        Assert.AreEqual("Refund confirmed", result.Message);
    }

    [TestMethod]
    public void ProcessWebhook_UnrecognizedEvent_ReturnsNotHandled()
    {
        var result = _gateway.ProcessWebhook("unknown.event", "{}");

        Assert.IsFalse(result.Handled);
        StringAssert.Contains(result.Message, "unknown.event");
    }

    // ── ProcessWebhook – negative / validation ───────────────

    [TestMethod]
    public void ProcessWebhook_NullEventType_ThrowsArgumentException()
    {
        Assert.ThrowsException<ArgumentException>(
            () => _gateway.ProcessWebhook(null!, "{}"));
    }

    [TestMethod]
    public void ProcessWebhook_EmptyPayload_ThrowsArgumentException()
    {
        Assert.ThrowsException<ArgumentException>(
            () => _gateway.ProcessWebhook("charge.succeeded", ""));
    }
}

